#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <Adafruit_MPU6050.h>
#include <Adafruit_Sensor.h>

LiquidCrystal_I2C lcdX(0x26, 16, 2);
LiquidCrystal_I2C lcdY(0x38, 16, 2);

Adafruit_MPU6050 mpu;

// --- СЕГМЕНТЫ ДЛЯ ЦИФР И СТРЕЛОК ---
uint8_t customChars[8][8] = {
  {0x1F, 0x1F, 0x1F, 0x00, 0x00, 0x00, 0x00, 0x00}, // 0: Верхняя полоса
  {0x1F, 0x1F, 0x1F, 0x1F, 0x1F, 0x1F, 0x1F, 0x1F}, // 1: Полный блок
  {0x00, 0x00, 0x00, 0x00, 0x00, 0x1F, 0x1F, 0x1F}, // 2: Нижняя полоса
  {0x1F, 0x1F, 0x1F, 0x00, 0x00, 0x00, 0x1F, 0x1F}, // 3: Верх и середина
  {0x04, 0x0E, 0x15, 0x04, 0x04, 0x04, 0x04, 0x00}, // 4: Стрелка ВВЕРХ
  {0x04, 0x04, 0x04, 0x04, 0x15, 0x0E, 0x04, 0x00}, // 5: Стрелка ВНИЗ
  {0x02, 0x06, 0x0E, 0x1E, 0x0E, 0x06, 0x02, 0x00}, // 6: Стрелка ВЛЕВО
  {0x08, 0x0C, 0x0E, 0x0F, 0x0E, 0x0C, 0x08, 0x00}  // 7: Стрелка ВПРАВО
};

// --- СЕГМЕНТЫ ДЛЯ ПРИВЕТСТВИЯ "БАЙКАЛ" ---
uint8_t baikalChars[8][8] = {
  {0x1E, 0x10, 0x10, 0x1E, 0x11, 0x11, 0x1E, 0x00}, // 0: Б (исправлено)
  {0x0E, 0x11, 0x11, 0x1F, 0x11, 0x11, 0x11, 0x00}, // 1: А
  {0x0A, 0x04, 0x11, 0x13, 0x15, 0x19, 0x11, 0x00}, // 2: Й
  {0x11, 0x12, 0x14, 0x18, 0x14, 0x12, 0x11, 0x00}, // 3: К
  {0x0F, 0x09, 0x09, 0x09, 0x09, 0x09, 0x19, 0x00}  // 4: Л
};

const char bigNumbers[10][2][3] = {
  { {1, 0, 1}, {1, 2, 1} },
  { {32, 1, 32}, {32, 1, 32} },
  { {0, 3, 1}, {1, 2, 2} },
  { {0, 3, 1}, {2, 2, 1} },
  { {1, 2, 1}, {32, 32, 1} },
  { {1, 3, 0}, {2, 2, 1} },
  { {1, 3, 0}, {1, 2, 1} },
  { {0, 0, 1}, {32, 32, 1} },
  { {1, 3, 1}, {1, 2, 1} },
  { {1, 3, 1}, {2, 2, 1} }
};

void loadCustomChars(LiquidCrystal_I2C &lcd) {
  for (int i = 0; i < 8; i++) {
    lcd.createChar(i, customChars[i]);
  }
}

// Приветствие "БАЙКАЛ" строго в 1 строке с затиранием слева направо
void showBaikalSplash(LiquidCrystal_I2C &lcd) {
  for (int i = 0; i < 5; i++) {
    lcd.createChar(i, baikalChars[i]);
  }

  // Отрисовка надписи БАЙКАЛ по центру 1-й строки (row 0, колонка 5)
  lcd.setCursor(5, 0);
  lcd.write(0); // Б
  lcd.write(1); // А
  lcd.write(2); // Й
  lcd.write(3); // К
  lcd.write(1); // А
  lcd.write(4); // Л

  delay(1200);

  // Анимация затирания слева направо по столбцам
  for (int col = 0; col < 16; col++) {
    lcd.setCursor(col, 0);
    lcd.print(" ");
    lcd.setCursor(col, 1);
    lcd.print(" ");
    delay(40);
  }
}

void printBigDigit(LiquidCrystal_I2C &lcd, int digit, int col) {
  if (digit < 0 || digit > 9) return;

  lcd.setCursor(col, 0);
  for (int i = 0; i < 3; i++) {
    char c = bigNumbers[digit][0][i];
    lcd.write(c == 32 ? ' ' : c);
  }

  lcd.setCursor(col, 1);
  for (int i = 0; i < 3; i++) {
    char c = bigNumbers[digit][1][i];
    lcd.write(c == 32 ? ' ' : c);
  }
}

void displayAngleX(LiquidCrystal_I2C &lcd, int angle) {
  int val = abs(angle);
  if (val > 99) val = 99;

  int tens = val / 10;
  int units = val % 10;

  lcd.setCursor(4, 0);
  if (angle < 0) {
    lcd.write(6); // Стрелка ВЛЕВО
  } else if (angle > 0) {
    lcd.write(7); // Стрелка ВПРАВО
  } else {
    lcd.print(" ");
  }

  lcd.setCursor(4, 1);
  lcd.print(" ");

  printBigDigit(lcd, tens, 6);
  printBigDigit(lcd, units, 10);
}

void displayAngleY(LiquidCrystal_I2C &lcd, int angle) {
  int val = abs(angle);
  if (val > 99) val = 99;

  int tens = val / 10;
  int units = val % 10;

  lcd.setCursor(4, 0);
  if (angle > 0) {
    lcd.write(4); // Стрелка ВВЕРХ
  } else if (angle < 0) {
    lcd.write(5); // Стрелка ВНИЗ
  } else {
    lcd.print(" ");
  }

  lcd.setCursor(4, 1);
  lcd.print(" ");

  printBigDigit(lcd, tens, 6);
  printBigDigit(lcd, units, 10);
}

void setup() {
  Wire.begin(21, 22);

  lcdX.init();
  lcdX.backlight();
  lcdX.clear();

  lcdY.init();
  lcdY.backlight();
  lcdY.clear();

  // Заставка "БАЙКАЛ" в первой строке
  showBaikalSplash(lcdX);
  showBaikalSplash(lcdY);

  // Возврат шрифта цифр и стрелок
  loadCustomChars(lcdX);
  loadCustomChars(lcdY);

  if (!mpu.begin()) {
    lcdX.setCursor(0, 0); lcdX.print("MPU Error!");
    lcdY.setCursor(0, 0); lcdY.print("MPU Error!");
    while (1) yield();
  }

  mpu.setAccelerometerRange(MPU6050_RANGE_8_G);
  mpu.setFilterBandwidth(MPU6050_BAND_21_HZ);
}

void loop() {
  sensors_event_t a, g, temp;
  mpu.getEvent(&a, &g, &temp);

  int angleX = atan2(a.acceleration.y, a.acceleration.z) * 180.0 / M_PI;
  int angleY = atan2(-a.acceleration.x, sqrt(a.acceleration.y * a.acceleration.y + a.acceleration.z * a.acceleration.z)) * 180.0 / M_PI;

  displayAngleX(lcdX, angleX);
  displayAngleY(lcdY, angleY);

  delay(200);
}
}
